class TestLexicalForms(unittest.TestCase):
    """Test the lexical forms which a recorded example can not hold."""

    def _read_with(self, xml_name: str, text: str) -> our_types.LevelType:
        """Read a recorded example with the content of ``xml_name`` put to ``text``."""
        paths = sorted(
            (tests.common.TEST_DATA_DIR / "Xml" / "Expected" / "levelType").glob(
                "**/*.xml"
            )
        )
        self.assertGreater(
            len(paths),
            0,
            "Expected at least one recorded example of levelType, but got none",
        )

        original = paths[0].read_text(encoding="utf-8")

        start = original.index(f"<{xml_name}>") + len(xml_name) + 2
        end = original.index(f"</{xml_name}>")

        return our_xmlization.level_type_from_str(
            original[:start] + text + original[end:]
        )

    def test_min_read_from_1(self) -> None:
        instance = self._read_with("min", "1")
        self.assertIs(True, instance.min)

    def test_min_read_from_0(self) -> None:
        instance = self._read_with("min", "0")
        self.assertIs(False, instance.min)

    def test_min_read_from_true(self) -> None:
        instance = self._read_with("min", "true")
        self.assertIs(True, instance.min)

    def test_min_read_from_false(self) -> None:
        instance = self._read_with("min", "false")
        self.assertIs(False, instance.min)


class TestDuplicateProperty(unittest.TestCase):
    """Test that a property given more than once is refused."""

    def test_duplicate_property(self) -> None:
        path = (
            tests.common.TEST_DATA_DIR
            / "Xml"
            / "Expected"
            / "extension"
            / "minimal.xml"
        )

        text = path.read_text(encoding="utf-8")

        start = text.find("<name>")
        if start >= 0:
            end = text.find("</name>", start)
            duplicated = text[start : end + 7]
        else:
            # The element is written self-closing in the example, an empty list
            # being the usual reason. We write that very element out ourselves.
            duplicated = "<name/>"

        insertion_index = text.rfind("</extension>")

        self.assertGreaterEqual(
            insertion_index,
            0,
            "Expected the recorded example to contain the closing tag "
            f"</extension>, but it does not: {path}",
        )

        broken_text = text[:insertion_index] + duplicated + text[insertion_index:]

        with self.assertRaises(our_xmlization.DeserializationException):
            our_xmlization.extension_from_str(broken_text)


if __name__ == "__main__":
    unittest.main()


